package com.example

import com.example.ExamQuestionHelper.QSpec

object HealthLiveExamReproductiveBank1 {
    private const val T = "නව යොවුන් විය, ප්‍රජනක සෞඛ්‍යය හා ලිංගික සම්ප්‍රේෂණ ආසාදන"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("ලෝක සෞඛ්‍ය සංවිධානය (WHO) මගින් නව යොවුන් විය (Adolescence) ලෙස නිල වශයෙන් නිර්වචනය කර ඇති වයස් සීමාව කුමක්ද?", "අවුරුදු 10 සිට 19 දක්වා කාලය", "අවුරුදු 5 සිට 12 දක්වා", "අවුරුදු 18 සිට 25 දක්වා", "අවුරුදු 12 සිට 15 දක්වා", "WHO නිර්වචනයට අනුව නව යොවුන් විය යනු වයස අවුරුදු 10ත් 19ත් අතර සංක්‍රාන්ති කාල පරිච්ඡේදයයි."),
        q("ළමා වියේ සිට වැඩිහිටි විය කරා එළඹෙන සංක්‍රාන්තික අවධියේදී ප්‍රජනක පද්ධතිය පරිණත වීම හඳුන්වන්නේ කෙසේද?", "යොවුන් වියට එළඹීම හෙවත් ප්‍රසාධනය (Puberty)", "ජරාජීර්ණ වීම", "ළමා සංවර්ධනය", "මධ්‍යම විය", "ප්‍රජනනය සඳහා ශරීරය කායිකව හා හෝමෝනමය වශයෙන් සූදානම් වීම ප්‍රසාධනය හෙවත් වැඩිවිය පැමිණීමයි."),
        q("නව යොවුන් වියේදී කායික වර්ධනය සහ හෝමෝන ක්‍රියාකාරිත්වය පාලනය කරන ප්‍රධාන මොළය පාමුල පිහිටි ග්‍රන්ථිය කුමක්ද?", "පිටියුටරි ග්‍රන්ථිය (Pituitary Gland)", "තයිරොයිඩ් ග්‍රන්ථිය", "අධිවෘක්ක ග්‍රන්ථිය", "අග්න්‍යාශය", "පිටියුටරි ග්‍රන්ථියෙන් නිපදවන FSH සහ LH හෝමෝන මගින් ලිංගික හෝමෝන ස්‍රාවය වීම උත්තේජනය කරයි."),
        q("පිරිමි දරුවන්ගේ ද්විතියික ලිංගික ලක්ෂණ පහළ වීමට ප්‍රධාන වශයෙන්ම බලපාන හෝමෝනය කුමක්ද?", "ටෙස්ටොස්ටෙරෝන් හෝමෝනය (Testosterone)", "ඊස්ට්‍රජන්", "ප්‍රොජෙස්ටරෝන්", "ඉන්සියුලින්", "වෘෂණවල ලීඩිග් සෛල මගින් ස්‍රාවය වන ටෙස්ටොස්ටෙරෝන් මගින් පිරිමි ලිංගික ලක්ෂණ පාලනය වේ."),
        q("ගැහැනු ළමුන්ගේ ද්විතියික ලිංගික ලක්ෂණ පහළ වීම හා ආර්තව චක්‍රය නියාමනය කරන ප්‍රධාන හෝමෝන දෙක මොනවාද?", "ඊස්ට්‍රජන් සහ ප්‍රොජෙස්ටරෝන් (Oestrogen & Progesterone)", "ටෙස්ටොස්ටෙරෝන් සහ තයිරොක්සින්", "ඇඩ්‍රිනලින් සහ කෝටිසෝල්", "ඉන්සියුලින් සහ ග්ලුකොගන්", "ඩිම්බ කෝෂ මගින් නිපදවන ඊස්ට්‍රජන් හා ප්‍රොජෙස්ටරෝන් මගින් කාන්තා ප්‍රජනක ලක්ෂණ පාලනය කෙරේ."),
        q("පිරිමි දරුවන්ගේ යොවුන් වියේදී උගුරු ඇටය (Adam's Apple) නෙරා ඒම සමග සිදුවන ප්‍රධාන ශාරීරික වෙනස කුමක්ද?", "ස්වරාලය විශාල වී කටහඬ ගොරෝසු වීම", "කටහඬ සිහින් වීම", "හිසකෙස් වැටීම", "උස යාම සම්පූර්ණයෙන් නැවතීම", "ස්වරාලය වර්ධනය වීම නිසා කටහඬ ගැඹුරු හා ගොරෝසු බවට පත්වේ."),
        q("ගැහැනු දරුවෙකුගේ ජීවිතයේ පළමු වරට සිදුවන ආර්තව රුධිර වහනය (පළමු ඔසප් වීම) හඳුන්වන්නේ කෙසේද?", "ආර්තවෝත්පාදය හෙවත් මෙනාකී (Menarche)", "ආර්තවාභාවය (Menopause)", "සංසේචනය", "ඩිම්බ මෝචනය", "කාන්තා ප්‍රජනක ජීවිතයේ ආරම්භය සනිටුහන් කරන ප්‍රථම ආර්තවය ආර්තවෝත්පාදය වේ."),
        q("වයස්ගත වීමත් සමග කාන්තාවන්ගේ ආර්තව චක්‍රය ස්ථිරවම නැවතී ප්‍රජනන හැකියාව අවසන් වීම හඳුන්වන්නේ කෙසේද?", "ආර්තවාභාවය හෙවත් මෙනපෝස් (Menopause)", "ආර්තවෝත්පාදය", "ඩිම්බ මෝචනය", "රෝපණය", "සාමාන්‍යයෙන් වයස අවුරුදු 45-55 අතර කාලයේදී හෝමෝන අඩුවීම නිසා ආර්තවය ස්ථිරව නැවතීම ආර්තවාභාවයයි."),
        q("පිරිමි දරුවන්ගේ වෘෂණ කෝෂ (Testes) උදර කුහරයෙන් පිටත වෘෂණ කෝෂ බෑගය (Scrotum) තුළ පිහිටා තිබීමේ ජීව විද්‍යාත්මක වාසිය කුමක්ද?", "ශුක්‍රාණු ජනනය සඳහා උදර කුහරයට වඩා සෙල්සියස් අංශක 2-3ක් අඩු උෂ්ණත්වයක් පවත්වා ගැනීම", "උෂ්ණත්වය වැඩි කිරීම", "රුධිර පීඩනය අඩු කිරීම", "හෝමෝන විනාශ කිරීම", "සාමාන්‍ය ශරීර උෂ්ණත්වයේදී සක්‍රීය ශුක්‍රාණු නිපදවිය නොහැකි බැවින් ශරීරයට වඩා අඩු සිසිල් පරිසරයක් වෘෂණ කෝෂ බෑගයෙන් සලසයි."),
        q("වෘෂණ තුළ නිපදවන නොමේරූ ශුක්‍රාණු තාවකාලිකව ගබඩා කර පරිණත භාවයට පත් කරන ස්ථානය කුමක්ද?", "අපිවෘෂණය (Epididymis)", "ශුක්‍ර ප්‍රණාලය", "පුරස්ථි ග්‍රන්ථිය", "මුත්‍ර ආශයිකාව", "ශුක්‍රාණුවලට චලන හැකියාව ලැබී පරිණත වන තෙක් අපිවෘෂණය තුළ ගබඩා වී පවතී."),
        q("පිරිමි ප්‍රජනක පද්ධතියේ ශුක්‍රාණු අපිවෘෂණයේ සිට මුත්‍ර මාර්ගය දෙසට ගෙන යන නාලය කුමක්ද?", "ශුක්‍ර ප්‍රණාලය (Vas Deferens)", "පැපොලෝපීය නාලය", "මුත්‍ර ප්‍රණාලය", "ස්නායු නාලය", "ශුක්‍රාණු ප්‍රවාහනය කරන ප්‍රධාන නාලය වන්නේ ශුක්‍ර ප්‍රණාලයයි."),
        q("ශුක්‍රාණුවලට ශක්තිය සැපයීම සඳහා ෆෲක්ටෝස් සීනි බහුල තරලයක් ස්‍රාවය කරන සහායක ග්‍රන්ථිය කුමක්ද?", "ශුක්‍ර ආශයිකාව (Seminal Vesicle)", "පුරස්ථි ග්‍රන්ථිය", "කූපර් ග්‍රන්ථිය", "තයිරොයිඩ් ග්‍රන්ථිය", "ශුක්‍ර ආශයිකා තරලයේ ඇති ෆෲක්ටෝස් ශුක්‍රාණුවල පිහිනුම් ශක්තිය සඳහා ATP නිපදවීමට උපකාරී වේ."),
        q("යෝනි මාර්ගයේ ආම්ලිකතාව උදාසීන කර ශුක්‍රාණු ආරක්ෂා කරන භෂ්මික තරලයක් ස්‍රාවය කරන ග්‍රන්ථිය කුමක්ද?", "පුරස්ථි ග්‍රන්ථිය (Prostate Gland)", "ශුක්‍ර ආශයිකාව", "පිටියුටරිය", "අධිවෘක්කය", "පුරස්ථි ග්‍රන්ථි ශ්‍රාවය මගින් යෝනි මාර්ගයේ ආම්ලික පරිසරයෙන් ශුක්‍රාණු මියයාම වළක්වයි."),
        q("පිරිමි සිරුරේ මුත්‍ර සහ ශුක්‍රාණු පිටවීම යන කාර්යයන් දෙකම සඳහා පොදුවේ භාවිත වන මාර්ගය කුමක්ද?", "ප්‍රවේග මාර්ගය හෙවත් මුත්‍ර ලිංගික මාර්ගය (Urethra)", "ශුක්‍ර ප්‍රණාලය පමණි", "මුත්‍ර වාහිනිය", "අපිවෘෂණය", "පිරිමින්ගේ ප්‍රවේග මාර්ගය ඔස්සේ මුත්‍ර මෙන්ම ශුක්‍ර තරලයද පිටතට නිකුත් කෙරේ."),
        q("කාන්තා ප්‍රජනක පද්ධතියේ ඩිම්බ සෛල නිපදවීම සහ හෝමෝන ස්‍රාවය කිරීම සිදුකරන ප්‍රධාන අවයවය කුමක්ද?", "ඩිම්බ කෝෂ (Ovaries)", "ගර්භාෂය", "පැපොලෝපීය නාලය", "යෝනි මාර්ගය", "කාන්තාවකගේ උදරයේ දෙපස පිහිටි ඩිම්බ කෝෂ යුගල මගින් ඩිම්බ හා කාන්තා ලිංගික හෝමෝන නිපදවයි."),
        q("ඩිම්බ කෝෂයේ සිට මුදාහරින පරිණත ඩිම්බය ලබාගෙන ගර්භාෂය දෙසට ප්‍රවාහනය කරන නාලය කුමක්ද?", "පැපොලෝපීය නාලය හෙවත් ඩිම්බ ප්‍රණාලය (Fallopian Tube)", "ශුක්‍ර ප්‍රණාලය", "යෝනි මාර්ගය", "මුත්‍ර මාර්ගය", "පැපොලෝපීය නාලයේ ඇති පක්ෂ්ම මගින් ඩිම්බය සෙමෙන් ගර්භාෂය දෙසට තල්ලු කෙරේ."),
        q("සාමාන්‍යයෙන් ශුක්‍රාණුවක් සහ ඩිම්බයක් එකිනෙක හමුවී සංසේචනය (Fertilization) සිදුවන්නේ ප්‍රජනක පද්ධතියේ කුමන ස්ථානයේදීද?", "පැපොලෝපීය නාලය තුළදී (Fallopian Tube)", "ගර්භාෂය තුළදී", "ඩිම්බ කෝෂය තුළදී", "යෝනි මාර්ගය තුළදී", "ස්වභාවික සංසේචනය සිදුවන්නේ පැපොලෝපීය නාලයේ ඉහළ තුනෙන් එකක කොටසේදීය."),
        q("සංසේචිත කළලය තැන්පත් වී දරු ප්‍රසූතිය දක්වා කලලය ආරක්ෂිතව වැඩෙන ඝන මාංශ පේශිමය අවයවය කුමක්ද?", "ගර්භාෂය (Uterus / Womb)", "ඩිම්බ කෝෂය", "පැපොලෝපීය නාලය", "මුත්‍ර ආශයිකාව", "ප්‍රසාරණය විය හැකි ශක්තිමත් පේශි බිත්තියක් සහිත ගර්භාෂය තුළ භ්‍රෑණය වර්ධනය වේ."),
        q("ආර්තව චක්‍රයේදී හෝමෝන බලපෑමෙන් ඝනකම් වී රුධිර නාලවලින් පිරී ගොස් සංසේචනයක් නොවූ විට ගැලවී යන ගර්භාෂ ඇතුළු ස්ථරය කුමක්ද?", "ගර්භාෂ අන්තඃස්තරය (Endometrium)", "මයෝමෙට්‍රියම්", "පෙරිටෝනියම්", "අපිචර්මය", "එන්ඩොමෙට්‍රියම් ස්ථරය බිඳ වැටී රුධිරය හා තරල සමග පිටවීම ආර්තව රුධිර වහනයයි."),
        q("නිරෝගී කාන්තාවකගේ සාමාන්‍ය ආර්තව චක්‍රයක (Menstrual Cycle) ආසන්න දින ගණන කොපමණද?", "දින 28කි (දින 21-35 අතර සාමාන්‍ය පරාසය)", "දින 14කි", "දින 40කි", "දින 7කි", "බොහෝ කාන්තාවන්ගේ ආර්තව චක්‍රයක් සාමාන්‍යයෙන් දින 28ක ආවර්තිතා කාලයකින් යුක්ත වේ."),
        q("දින 28ක සම්මත ආර්තව චක්‍රයකදී ඩිම්බ කෝෂයෙන් පරිණත ඩිම්බයක් මුදාහැරීම හෙවත් ඩිම්බ මෝචනය (Ovulation) සිදුවන සාමාන්‍ය දිනය කුමක්ද?", "14 වන දිනය (Day 14)", "1 වන දිනය", "7 වන දිනය", "28 වන දිනය", "ආර්තවය ආරම්භ වූ පළමු දින සිට ගණන් කළ විට 14 වන දිනයේදී පමණ ඩිම්බ මෝචනය සිදුවේ."),
        q("ඩිම්බ කෝෂයෙන් ඩිම්බයක් පිටවීම හෙවත් ඩිම්බ මෝචනය (Ovulation) ක්ෂණිකව උත්තේජනය කරන පිටියුටරි හෝමෝනය කුමක්ද?", "ලූටිනයිසිං හෝමෝනය (LH — LH Surge)", "FSH හෝමෝනය", "ඉන්සියුලින්", "තයිරොක්සින්", "රුධිරයේ LH හෝමෝනය ක්ෂණිකව ඉහළ යාම (LH surge) නිසා ඩිම්බ කෝෂයෙන් පරිණත ඩිම්බය පිටවේ."),
        q("ඩිම්බ මෝචනයෙන් පසු ඩිම්බ කෝෂයේ ඉතිරි වන ෆොලිකලය කහ පැහැති ග්‍රන්ථිමය ව්‍යුහයක් බවට පත්වීම හඳුන්වන්නේ කෙසේද?", "කහ දේහය හෙවත් කෝපස් ලූටියම් (Corpus Luteum)", "සුදු දේහය", "ඩිම්බ සෛලය", "කලලය", "කෝපස් ලූටියම් මගින් ප්‍රොජෙස්ටරෝන් හෝමෝනය විශාල වශයෙන් ස්‍රාවය කර ගර්භාෂ අන්තඃස්තරය ආරක්ෂා කරයි."),
        q("ආර්තව දිනවලදී සනීපාරක්ෂක තුවා (Sanitary Napkins) කොපමණ කාලයකට වරක් මාරු කළ යුතුද?", "පැය 4 සිට 6 දක්වා වරක්වත්", "දිනකට එක් වරක් පමණක්", "දින 2කට වරක්", "පැය 24කට වරක්", "බැක්ටීරියා ආසාදන හා දුගඳ හැමීම වැළැක්වීමට අවම වශයෙන් පැය 4-6කට වරක්වත් සනීපාරක්ෂක තුවා මාරු කළ යුතුය."),
        q("භාවිත කළ සනීපාරක්ෂක තුවා බැහැර කිරීමේ වඩාත් සෞඛ්‍යාරක්ෂිත හා නිවැරදි ක්‍රමවේදය කුමක්ද?", "පත්තර හෝ කඩදාසියක හොඳින් ඔතා කසළ බඳුනකට දැමීම හෝ ආරක්ෂිතව පිළිස්සීම", "වැසිකිලි පෝච්චියට දමා ෆ්ලෂ් කිරීම", "කාණු හෝ විවෘත පරිසරයට විසි කිරීම", "පොළොවේ මතුපිට දැමීම", "වැසිකිලි පෝච්චියට දැමීමෙන් නළ අවහිර වන අතර විවෘතව දැමීමෙන් පාරිසරික හා සෞඛ්‍ය උවදුරු හටගනී."),
        q("ශුක්‍රාණුවක න්‍යෂ්ටිය සහ ඩිම්බයක න්‍යෂ්ටිය එකිනෙක ඒකාබද්ධ වී තනි ද්විගුණ සෛලයක් සෑදීමේ ක්‍රියාවලිය කුමක්ද?", "සංසේචනය (Fertilization)", "ඩිම්බ මෝචනය", "ප්‍රසාධනය", "ආර්තවය", "සංසේචනයෙන් පසු සෑදෙන තනි ද්විගුණ (2n) සෛලය යුක්තානුව (Zygote) ලෙස හැඳින්වේ."),
        q("සංසේචනයෙන් පසු සෑදුණු ඒක සෛලීය යුක්තානුව වේගයෙන් සෛල බෙදෙමින් පැමිණ ගර්භාෂ බිත්තියේ තැන්පත් වීම කුමක්ද?", "රෝපණය (Implantation)", "ඩිම්බ මෝචනය", "ප්‍රසූතිය", "සංසේචනය", "සංසේචනයෙන් දින 6-7කට පසු බ්ලාස්ටොසිස්ටය ගර්භාෂ අන්තඃස්තරයේ සවිවීම රෝපණයයි."),
        q("ගර්භණී සමයේදී මවගේ රුධිරය සහ කලලයේ රුධිරය අතර පෝෂ්‍ය පදාර්ථ හා වායු හුවමාරු කරන සුවිශේෂී තාවකාලික ඉන්ද්‍රිය කුමක්ද?", "වැදෑමහ (Placenta)", "ඩිම්බ කෝෂය", "පැපොලෝපීය නාලය", "හෘදය", "වැදෑමහ මගින් මවගේ සහ කලලයේ රුධිරය සෘජුව මිශ්‍ර නොවී පෝෂණය, ඔක්සිජන් හා ප්‍රතිදේහ සපයයි."),
        q("කලලයේ පෙකණිය සහ වැදෑමහ එකිනෙක සම්බන්ධ කරන රුධිර වාහිනී සහිත නාලය හඳුන්වන්නේ කෙසේද?", "පෙකණි වැල හෙවත් නහය වැල (Umbilical Cord)", "ශුක්‍ර ප්‍රණාලය", "ස්නායු නාලය", "පැපොලෝපීය නාලය", "පෙකණි වැල තුළ ධමනි 2ක් (අපද්‍රව්‍ය ගෙන යන) සහ ශිරාවක් (පෝෂණය හා ඔක්සිජන් ගෙන යන) අඩංගු වේ."),
        q("ගර්භාෂය තුළ වැඩෙන කලලය වටා ඇති උල්බ තරලයෙන් (Amniotic Fluid) ඉටුවන ප්‍රධාන ආරක්ෂිත කාර්යය කුමක්ද?", "බාහිර කම්පන හා පීඩනවලින් කලලය ආරක්ෂා කිරීම සහ ඒකාකාර උෂ්ණත්වයක් පවත්වා ගැනීම", "කලලයට ඇවිදීමට ඉඩ දීම", "කලලයේ ආහාර දිරවීම", "කලලයේ සම වියළීම", "උල්බ තරලය කම්පන අවශෝෂකයක් ලෙස ක්‍රියා කරමින් කලලයට නිදහසේ අවයව චලනය කිරීමට ඉඩ සලසයි."),
        q("නව යොවුන් වියේදී (අවුරුදු 18ට අඩු) ගැබ් ගැනීමක් සිදුවීමෙන් මවට ඇතිවන බරපතළම කායික සෞඛ්‍ය අවදානම කුමක්ද?", "ශ්‍රෝණි අස්ථි සම්පූර්ණ වර්ධනය වී නොමැති වීම නිසා ප්‍රසූතියේදී ඇතිවන අවහිරතා සහ අධික රුධිර වහනය", "අස්ථි වේගයෙන් ශක්තිමත් වීම", "ආහාර රුචිය වැඩිවීම", "ශරීරය නිරෝගී වීම", "නොමේරූ උකුල් ඇට නිසා ප්‍රසූතිය අවහිර වීමෙන් මව මෙන්ම දරුවාද මරණයට පත්වීමේ අවදානම ඉතා ඉහළය."),
        q("යොවුන් වියේ මව්වරුන්ට උපදින දරුවන් මුහුණ දෙන ප්‍රධාන සෞඛ්‍ය ගැටලුවක් වන්නේ කුමක්ද?", "උපතේදී බර අඩු වීම (Low birth weight) සහ නොමේරූ දරු උපත්", "අධික බරින් යුතුව උපත ලැබීම", "ප්‍රතිශක්තිය ඉතා ඉහළ වීම", "ක්ෂණිකව කතා කිරීමට හැකිවීම", "යොවුන් මවගේ පෝෂණ ඌනතා නිසා උපදින දරුවන් අඩු බරැති සහ නොමේරූ දරුවන් වීමේ සම්භාවිතාව වැඩිය."),
        q("ශ්‍රී ලංකා නීතියට අනුව වයස අවුරුදු 16ට අඩු දැරියක සමග ඇයගේ කැමැත්තෙන් හෝ අකමැත්තෙන් ලිංගිකව එක්වීම සලකනු ලබන්නේ කුමන වරදක් ලෙසද?", "ව්‍යවස්ථාපිත ස්ත්‍රී දූෂණය (Statutory Rape) නම් වූ බරපතළ අපරාධයක් ලෙස", "සුළු වැරැද්දක් ලෙස", "නීත්‍යානුකූල එකඟතාවක් ලෙස", "පවුලේ ආරවුලක් ලෙස", "නීතිය අනුව අවුරුදු 16ට අඩු දරුවන්ට ලිංගික කටයුතු සඳහා නීත්‍යානුකූල කැමැත්තක් ලබාදිය නොහැක."),
        q("ලිංගික සංසර්ගය මගින් එක් අයෙකුගෙන් තවත් අයෙකුට බෝවන බෝවන රෝග පොදුවේ හඳුන්වන්නේ කෙසේද?", "ලිංගික සම්ප්‍රේෂණ ආසාදන (STIs / STDs)", "පෝෂණ ඌනතා රෝග", "ජානමය රෝග", "ශ්වසන රෝග", "ලිංගික ක්‍රියාකාරකම් මගින් බැක්ටීරියා, වෛරස හෝ පරපෝෂිතයන් සම්ප්‍රේෂණය වීම STIs වේ."),
        q("ට්‍රෙපොනේමා පැලිඩම් (Treponema pallidum) නම් බැක්ටීරියාව මගින් බෝවන ලිංගික රෝගය කුමක්ද?", "සිෆිලිස් රෝගය (Syphilis)", "ගොනෝරියාව", "ඒඩ්ස්", "හර්පීස්", "සිෆිලිස් රෝගයේ ප්‍රාථමික අවධියේදී ප්‍රජනක අවයව ආශ්‍රිතව වේදනා රහිත තුවාලයක් (Chancre) හටගනී."),
        q("නයිසීරියා ගොනෝරියේ (Neisseria gonorrhoeae) නම් බැක්ටීරියාව නිසා හටගන්නා ලිංගික රෝගය කුමක්ද?", "ගොනෝරියාව (Gonorrhoea)", "සිෆිලිස්", "හර්පීස්", "හෙපටයිටිස්", "ගොනෝරියා රෝගයේදී මුත්‍ර කරන විට දැවිල්ල සහ සැරව වැනි ශ්‍රාවයන් පිටවීම සිදුවේ."),
        q("හර්පීස් සිම්ප්ලෙක්ස් වෛරසය (HSV-2) මගින් ප්‍රජනක අවයව ආශ්‍රිතව ඇතිවන වේදනාකාරී ආසාදනය කුමක්ද?", "ලිංගික හර්පීස් (Genital Herpes)", "සිෆිලිස්", "ගොනෝරියාව", "ක්ලැමීඩියා", "HSV වෛරසය මගින් ලිංගාශ්‍රිතව වේදනාකාරී දිය බිබිලි හා තුවාල හටගන්නා අතර එය නැවත නැවත මතුවේ."),
        q("මානව පැපිලෝමා වෛරසය (HPV) මගින් කාන්තාවන් තුළ හටගත හැකි වඩාත්ම මාරාන්තික පිළිකා වර්ගය කුමක්ද?", "ගැබ්ගෙල පිළිකාව (Cervical Cancer)", "පියයුරු පිළිකාව", "අක්මා පිළිකාව", "පෙනහලු පිළිකාව", "HPV හි අධි අවදානම් ප්‍රභේද මගින් ගැබ්ගෙල පිළිකා ඇති කරන අතර ඒ සඳහා පාසල් දැරියන්ට එන්නත ලබාදේ."),
        q("ශ්‍රී ලංකාවේ පාසල්වල 6 වන ශ්‍රේණියේ ගැහැනු ළමුන්ට නොමිලේ ලබාදෙන HPV එන්නත මගින් වළක්වා ගන්නේ කුමන රෝගයද?", "ගැබ්ගෙල පිළිකාව (Cervical Cancer)", "රුබෙල්ලා", "පිටගැස්ම", "මී උණ", "HPV එන්නත ලබාදීමෙන් ගැබ්ගෙල පිළිකා ඇතිවීමෙන් විශිෂ්ට ආරක්ෂාවක් සැලසේ."),
        q("මානව ප්‍රතිශක්ති ඌනතා වෛරසය (HIV) මගින් ශරීරයේ විනාශ කරනු ලබන ප්‍රධාන සෛල වර්ගය කුමක්ද?", "CD4+ T උපකාරක ලිම්ෆොසයිට සෛල (T-helper cells)", "රතු රුධිර සෛල", "රුධිර පට්ටිකා", "ස්නායු සෛල", "HIV වෛරසය ප්‍රතිශක්තිකරණ පද්ධතියේ ප්‍රධාන සෙන්පතියා වන CD4 T සෛල විනාශ කර ප්‍රතිශක්තිය බිඳ දමයි."),
        q("HIV ආසාදනය වී වසර ගණනාවකට පසු ශරීරයේ ප්‍රතිශක්තිය සම්පූර්ණයෙන්ම බිඳ වැටී අවස්ථාවාදී ආසාදන වැළඳෙන අවසන් අවධිය කුමක්ද?", "ඒඩ්ස් තත්ත්වය (AIDS — Acquired Immunodeficiency Syndrome)", "ප්‍රාථමික උණ", "කවුළු කාලය", "සුවපත් වීම", "AIDS යනු HIV ආසාදනයේ උච්චතම හා අවසන් අවධියයි."),
        q("HIV වෛරසය එක් පුද්ගලයෙකුගෙන් තවත් අයෙකුට සම්ප්‍රේෂණය විය හැකි ප්‍රධාන මාර්ගය කුමක්ද?", "ආරක්ෂිත නොවන අනාරක්ෂිත ලිංගික සබඳතා පැවැත්වීම", "අතට අත දීම", "එකට ආහාර ගැනීම", "මදුරුවන් දෂ්ට කිරීම", "HIV සම්ප්‍රේෂණය වන ප්‍රධානතම මාර්ගය වන්නේ ආසාදිත ලිංගික තරල හුවමාරුවයි."),
        q("HIV වෛරසය සම්ප්‍රේෂණය වන තවත් ප්‍රධාන වෛද්‍යමය මාර්ගයක් වන්නේ කුමක්ද?", "ආසාදිත රුධිරය පාරවිලයනය සහ විෂබීජහරණය නොකළ එන්නත් කටු හවුලේ භාවිතය", "දුරකථන භාවිතය", "පොදු වැසිකිලි භාවිතය", "එකම කාමරයේ නිදා ගැනීම", "මත්වතුර හෝ මත්ද්‍රව්‍ය ගන්නන් අතර එන්නත් කටු හවුලේ භාවිත කිරීමෙන් HIV වේගයෙන් බෝවේ."),
        q("HIV ආසාදිත මවකගෙන් දරුවාට වෛරසය සම්ප්‍රේෂණය විය හැකි අවස්ථා මොනවාද?", "ගර්භණී සමයේදී, දරු ප්‍රසූතියේදී සහ මව්කිරි දීමේදී", "දරුවා වඩා ගැනීමේදී පමණක්", "දරුවා නැළවීමේදී", "දරුවාට ඇඳුම් ඇන්දවීමේදී", "ප්‍රසව සමයේදී හා මව්කිරි මගින් දරුවාට HIV යා හැකි වුවද නිසි ප්‍රතිකාර මගින් එය සම්පූර්ණයෙන්ම පාහේ වැළැක්විය හැක."),
        q("HIV වෛරසය කිසිසේත්ම සම්ප්‍රේෂණය නොවන ක්‍රියාකාරකමක් වන්නේ කුමක්ද?", "අතට අත දීම, බදා වැළඳ ගැනීම, එකට ආහාර ගැනීම සහ පිහිනුම් තටාක භාවිතය", "අනාරක්ෂිත ලිංගික සබඳතා", "ලේ දීම හෝ ගැනීම", "එන්නත් කටු හවුලේ භාවිතය", "සාමාන්‍ය සමාජ ඇසුරෙන් හෝ කෙළ, දහඩිය, කඳුළු මගින් HIV බෝ නොවේ."),
        q("මදුරුවන් හෝ වෙනත් කෘමීන් දෂ්ට කිරීම මගින් HIV වෛරසය බෝ නොවීමට ප්‍රධාන විද්‍යාත්මක හේතුව කුමක්ද?", "HIV වෛරසයට මදුරුවාගේ සිරුර තුළ ගුණනය වීමට නොහැකි වීම සහ මදුරුවා ලේ එන්නත් නොකිරීම", "මදුරුවා ලේ නොබොන නිසා", "මදුරුවන්ගේ වස නිසා", "මදුරුවා කුඩා සතෙකු නිසා", "මදුරුවාගේ ජීර්ණ පද්ධතියේදී HIV විනාශ වන අතර ඌ වෙනත් අයෙකුට විදින්නේ කෙළ පමණි."),
        q("HIV වෛරසය ශරීරගත වූ මුල් කාලයේ ප්‍රතිදේහ පරීක්ෂණවලට හසු නොවන නමුත් රෝගය අන් අයට බෝවිය හැකි කාල සීමාව කුමක්ද?", "කවුළු කාලය හෙවත් වින්ඩෝ පීරියඩ් (Window Period)", "පුර්වෝත්පාදන කාලය", "සුවවීමේ කාලය", "ප්‍රතිශක්ති කාලය", "සාමාන්‍යයෙන් සති 3 සිට මාස 3 දක්වා කාලය තුළ රුධිරයේ ප්‍රමාණවත් ප්‍රතිදේහ නිපදවී නොමැති බැවින් පරීක්ෂණවලට හසු නොවේ."),
        q("HIV ආසාදිතයන් සඳහා වෛරසයේ ගුණනය පාලනය කර ආයු කාලය දීර්ඝ කිරීමට ලබාදෙන සම්මත ඖෂධ ප්‍රතිකාරය කුමක්ද?", "ප්‍රති-ප්‍රතිවර්තක ප්‍රතිකාරය (ART — Antiretroviral Therapy)", "පෙනිසිලින් ප්‍රතිකාරය", "ඉන්සියුලින් ප්‍රතිකාරය", "ශල්‍යකර්ම", "ART ඖෂධ මගින් වෛරස ප්‍රමාණය ඉතා අවම මට්ටමකට ගෙනැවිත් සාමාන්‍ය නිරෝගී ජීවිතයක් ගත කිරීමට ඉඩ සලසයි."),
        q("ශ්‍රී ලංකාවේ ලිංගික රෝග හා HIV පිළිබඳ නොමිලේ හා රහස්‍යභාවය සුරකිමින් පරීක්ෂණ පවත්වන රජයේ ප්‍රධාන ආයතනය කුමක්ද?", "ජාතික ලිංගාශ්‍රිත රෝග හා ඒඩ්ස් මර්දන ව්‍යාපාරය (NSACP)", "මහජන සෞඛ්‍ය දෙපාර්තමේන්තුව", "ඖෂධ නියාමන අධිකාරිය", "ජාතික රුධිර පාරවිලයන මධ්‍යස්ථානය", "NSACP යටතේ දිවයින පුරා පිහිටි ලිංගාශ්‍රිත රෝග සායන (STD Clinics) මගින් රහස්‍ය පරීක්ෂණ හා ප්‍රතිකාර නොමිලේ සැපයේ."),
        q("HIV ආසාදිත පුද්ගලයන් සමාජයෙන් කොන් කිරීම හා අපකීර්තියට ලක් කිරීම (Stigma & Discrimination) නුසුදුසු වන්නේ මන්ද?", "එය මානව හිමිකම් උල්ලංඝනය කිරීමක් වන අතර රෝගීන් බියෙන් පරීක්ෂණ හා ප්‍රතිකාරවලින් සැඟවී රෝගය පැතිරීමට හේතු වන බැවින්", "රෝගීන් අපරාධකරුවන් නිසා", "රෝගය වාතයෙන් බෝවන නිසා", "කිසිදු ගැටලුවක් නැති නිසා", "කොන් කිරීම නිසා රෝගීන් ප්‍රතිකාරවලට යොමු නොවී සමාජය තුළ වෛරසය තවදුරටත් රහසිගතව පැතිර යාම සිදුවේ."),
        q("HIV රෝගය තහවුරු කරගැනීම සඳහා භාවිත කරන ප්‍රධාන රසායනාගාර පරීක්ෂණ ක්‍රමවේදය කුමක්ද?", "ELISA සහ වෙස්ටර්න් බ්ලොට් (Western Blot) පරීක්ෂාව", "රුධිර සීනි පරීක්ෂාව", "මුත්‍ර පරීක්ෂාව", "එක්ස් කිරණ පරීක්ෂාව", "ELISA මගින් මුලින්ම ප්‍රතිදේහ හඳුනාගෙන පසුව වෙස්ටර්න් බ්ලොට් හෝ PCR මගින් ආසාදනය ස්ථිරව තහවුරු කරයි."),
        q("නව යොවුන් වියේදී සිදුවන ශාරීරික උස සහ බර වේගයෙන් ඉහළ යාම හඳුන්වන්නේ කෙසේද?", "වර්ධන පිම්ම හෙවත් වර්ධනය වේගවත් වීම (Growth Spurt)", "වර්ධන පරිහානිය", "අකාල වර්ධනය", "ආර්තවාභාවය", "හෝමෝන බලපෑම නිසා කෙටි කාලයකදී ශරීරයේ අස්ථි හා පේශි ක්ෂණිකව වර්ධනය වීම Growth Spurt වේ."),
        q("සාමාන්‍යයෙන් පිරිමි ළමුන්ට වඩා ගැහැනු ළමුන්ගේ වර්ධන පිම්ම කලින් ආරම්භ වීමට හේතුව කුමක්ද?", "ගැහැනු ළමුන්ගේ ප්‍රසාධනය (Puberty) පිරිමි ළමුන්ට වඩා වසර 1-2ක් කලින් සිදුවීම", "ගැහැනු ළමුන් ආහාර වැඩිපුර ගැනීම", "පිරිමි ළමුන් ක්‍රීඩා නොකිරීම", "ජානමය හේතු නොමැති වීම", "ගැහැනු දරුවන් වයස 10-12 දී ප්‍රසාධනයට පත්වන අතර පිරිමි දරුවන් වයස 12-14 දී ප්‍රසාධනය වේ."),
        q("පිරිමි දරුවන්ගේ නින්දේදී සිදුවන ස්වභාවික ශුක්‍ර මෝචනය හඳුන්වන්නේ කෙසේද?", "රාත්‍රී විමෝචනය හෙවත් තෙත් සිහිනය (Nocturnal Emission)", "අකාල මෝචනය", "ආර්තවය", "ශුක්‍රාණු විනාශය", "පිරිමි දරුවන්ගේ ප්‍රජනක පද්ධතිය පරිණත වීමත් සමග නින්දේදී ශුක්‍ර තරලය පිටවීම ස්වභාවික සිදුවීමකි."),
        q("රාත්‍රී විමෝචනය (Nocturnal Emission) සම්බන්ධයෙන් නව යොවුන් වියේ පිරිමි දරුවෙකු තේරුම් ගත යුතු නිවැරදි කරුණ කුමක්ද?", "එය කිසිදු රෝගයක් නොවන අතර ප්‍රජනක පද්ධතිය පරිණත වීමේ සාමාන්‍ය ස්වභාවික ලක්ෂණයකි", "එය බරපතළ රෝගයකි", "එයින් ශරීර ශක්තිය විනාශ වේ", "වහාම ඖෂධ ගත යුතුය", "රාත්‍රී විමෝචනය යනු වැඩිවිය පැමිණීමේදී සිදුවන සම්පූර්ණයෙන්ම සාමාන්‍ය හා නිරෝගී ක්‍රියාවලියකි."),
        q("කාන්තා ප්‍රජනක පද්ධතියේ ගැබ්ගෙල (Cervix) පිහිටා ඇත්තේ කොතැනද?", "ගර්භාෂයේ පහළ පටු කෙළවර සහ යෝනි මාර්ගය අතර", "ඩිම්බ කෝෂය අසල", "පැපොලෝපීය නාලයේ කෙළවර", "උදර බිත්තියේ", "ගර්භාෂයේ පහළ පටු විවරය ගැබ්ගෙල වන අතර එය යෝනි මාර්ගයට විවෘත වේ."),
        q("ඩිම්බ කෝෂ තුළ ඩිම්බ සෛලයක් පරිණත වන කුඩා බුබුලක් බඳු ව්‍යුහය හඳුන්වන්නේ කෙසේද?", "ඩිම්බ කෝෂ ෆොලිකලය (Graafian Follicle)", "කහ දේහය", "ශුක්‍රාණුව", "යුක්තානුව", "ඩිම්බ කෝෂයේ ඇති ෆොලිකලය තුළ ඩිම්බය වර්ධනය වී පරිණත වේ."),
        q("කාන්තාවකගේ ශරීරයේ ඩිම්බයක් සංසේචනය නොවූ විට එය ශරීරය තුළ ජීවීව පවතින සාමාන්‍ය කාලය කොපමණද?", "පැය 12 සිට 24 දක්වා කාලයක්", "දින 7ක්", "පැය 72ක්", "විනාඩි 10ක්", "ඩිම්බ මෝචනයෙන් පසු ඩිම්බයක ආයු කාලය පැය 12-24 අතර කෙටි කාලයකි."),
        q("පිරිමි ශුක්‍රාණුවකට කාන්තා ප්‍රජනක පද්ධතිය තුළ සංසේචනය වීමේ හැකියාව රඳවා ගත හැකි සාමාන්‍ය කාලය කොපමණද?", "පැය 48 සිට 72 දක්වා (දින 2-3ක්)", "පැය 2ක් පමණි", "දින 10ක්", "විනාඩි 30ක්", "ශුක්‍රාණුවලට කාන්තා ප්‍රජනක මාර්ගය තුළ දින 2-3ක් පමණ සක්‍රීයව ජීවත් විය හැක."),
        q("දරුවෙකුගේ ලිංගය (ගැහැනු ද පිරිමි ද යන්න) ජානමය වශයෙන් තීරණය කරනු ලබන්නේ කාගේ ලිංග වර්ණදේහ මගින්ද?", "පියාගේ ශුක්‍රාණුවේ ඇති X හෝ Y වර්ණදේහය මගින්", "මවගේ ඩිම්බය මගින් පමණි", "ආහාර රටාව මගින්", "පරිසර උෂ්ණත්වය මගින්", "පියාගේ ශුක්‍රාණුව X ද Y ද යන්න මත දරුවාගේ ලිංගය තීරණය වේ."),
        q("පිරිමි ශුක්‍රාණුවක ඇති ලිංග වර්ණදේහ වර්ග දෙක මොනවාද?", "X වර්ණදේහය සහ Y වර්ණදේහය", "X පමණි", "Y පමණි", "Z සහ W වර්ණදේහ", "පිරිමින් නිපදවන ශුක්‍රාණුවලින් 50%ක් X වර්ණදේහයද 50%ක් Y වර්ණදේහයද දරයි."),
        q("කාන්තා ඩිම්බ සෛලයක අඩංගු වන්නේ කුමන ලිංග වර්ණදේහය පමණක්ද?", "X වර්ණදේහය පමණි", "Y වර්ණදේහය පමණි", "X සහ Y දෙකම", "කිසිදු වර්ණදේහයක් නැත", "කාන්තාවන් සතුව ඇත්තේ XX වර්ණදේහ බැවින් සියලුම ඩිම්බවල ඇත්තේ X වර්ණදේහය පමණි."),
        q("මවගේ X වර්ණදේහය සහිත ඩිම්බයක් පියාගේ Y වර්ණදේහය සහිත ශුක්‍රාණුවක් සමග සංසේචනය වූ විට බිහිවන දරුවාගේ ලිංගය කුමක්ද?", "පිරිමි දරුවෙකි (XY)", "ගැහැනු දරුවෙකි (XX)", "නිවුන් දරුවන්", "තීරණය කළ නොහැක", "XY සංයෝජනය පිරිමි දරුවෙකු බිහි කරයි."),
        q("මවගේ X වර්ණදේහය සහිත ඩිම්බයක් පියාගේ X වර්ණදේහය සහිත ශුක්‍රාණුවක් සමග සංසේචනය වූ විට බිහිවන දරුවා කවුරුන්ද?", "ගැහැනු දරුවෙකි (XX)", "පිරිමි දරුවෙකි (XY)", "ආබාධිත දරුවෙකි", "කිසිවෙක් නොවේ", "XX සංයෝජනය ගැහැනු දරුවෙකු බිහි කරයි."),
        q("දරුවෙකුගේ ලිංගය තීරණය වීමේදී මවට දොස් පැවරීම විද්‍යාත්මකව මුළාවක් වන්නේ මන්ද?", "මව සතුව ඇත්තේ X වර්ණදේහ පමණක් වන අතර ලිංගය තීරණය කරන Y වර්ණදේහය ඇත්තේ පියා සතුව පමණක් වන බැවින්", "මව දරුවා බිහි කරන නිසා", "වර්ණදේහ වෙනස් කළ හැකි නිසා", "කිසිදු හේතුවක් නැත", "දරුවා පිරිමි දරුවෙකු වීමට අවශ්‍ය Y වර්ණදේහය සම්ප්‍රේෂණය වන්නේ පියාගෙන් පමණි."),
        q("එකම ඩිම්බයක් තනි ශුක්‍රාණුවකින් සංසේචනය වී සෑදුණු යුක්තානුව දෙකට බෙදී වර්ධනය වීමෙන් බිහිවන නිවුන් දරුවන් කවුරුන්ද?", "ඒකයුක්තානු හෙවත් සර්වසම නිවුන් දරුවන් (Identical Twins)", "ද්වි-යුක්තානු නිවුන් දරුවන්", "අසර්වසම දරුවන්", "සාමාන්‍ය දරුවන්", "සර්වසම නිවුන් දරුවන් ජානමය වශයෙන් 100%ක් සමාන වන අතර එකම ලිංගයට අයත් වේ."),
        q("වෙන වෙනම ඩිම්බ දෙකක් ශුක්‍රාණු දෙකකින් සංසේචනය වීමෙන් බිහිවන නිවුන් දරුවන් හඳුන්වන්නේ කෙසේද?", "ද්වි-යුක්තානු හෙවත් අසර්වසම නිවුන් දරුවන් (Fraternal Twins)", "සර්වසම නිවුන් දරුවන්", "ඒකයුක්තානු දරුවන්", "පිටපත් දරුවන්", "වෙනම ඩිම්බ දෙකකින් බිහිවන බැවින් මෙම දරුවන් එකිනෙකාට ජානමය වශයෙන් වෙනස් විය හැක."),
        q("ප්‍රසූතියේදී ගර්භාෂ බිත්තියේ ප්‍රබල පේශි සංකෝචනය ඇති කරන පිටියුටරි හෝමෝනය කුමක්ද?", "ඔක්සිටොසින් හෝමෝනය (Oxytocin)", "ප්‍රොලැක්ටින්", "තයිරොක්සින්", "ඉන්සියුලින්", "ඔක්සිටොසින් මගින් ගර්භාෂ පේශි තදින් හැකිළී දරුවා යෝනි මාර්ගය ඔස්සේ පිටතට තල්ලු කෙරේ."),
        q("මව්කිරි නිපදවීම උත්තේජනය කරන ප්‍රධාන හෝමෝනය කුමක්ද?", "ප්‍රෝලැක්ටින් හෝමෝනය (Prolactin)", "ඔක්සිටොසින්", "ඊස්ට්‍රජන්", "ටෙස්ටොස්ටෙරෝන්", "පිටියුටරි ග්‍රන්ථියෙන් නිපදවන ප්‍රෝලැක්ටින් හෝමෝනය මගින් පියයුරුවල කිරි නිපදවීම උත්තේජනය කරයි."),
        q("දරු ප්‍රසූතියෙන් පසු මුල් දින 2-3 තුළ මවගෙන් ස්‍රාවය වන කහ පැහැති ප්‍රතිදේහ පිරි මව්කිරි හඳුන්වන්නේ කෙසේද?", "කොලොස්ට්‍රම් හෙවත් රන් කිරි (Colostrum)", "පෙර කිරි", "පසු කිරි", "දිය කිරි", "කොලොස්ට්‍රම් තුළ ළදරුවා ලෙඩ රෝගවලින් ආරක්ෂා කරන ප්‍රතිදේහ (IgA) සහ සුදු රුධිරාණු අතිවිශාල ප්‍රමාණයක් අඩංගු වේ."),
        q("බිළිඳා ඉපදී මුල් මාස 6 තුළ දිය යුත්තේ කුමක් පමණක්ද?", "මව්කිරි පමණි (Exclusive Breastfeeding)", "මව්කිරි සහ ජලය", "පිටි කිරි", "තේ සහ දොඩම් යුෂ", "මුල් මාස 6 තුළ බිළිඳාට අවශ්‍ය සම්පූර්ණ පෝෂණය හා ජලය මව්කිරිවලින් පමණක් ලැබේ."),
        q("උපතින් පසු මුල් මාස 6 තුළ බිළිඳාට මව්කිරි හැර වතුර හෝ වෙනත් කිසිදු දියරයක් නොදිය යුත්තේ මන්ද?", "මව්කිරිවල සියලු පෝෂ්‍ය පදාර්ථ හා ජලය නියමිත අනුපාතයට අඩංගු වන අතර වෙනත් ද්‍රව්‍යවලින් ආසාදන ඇතිවිය හැකි බැවින්", "බඩ පිරෙන නිසා", "කිරි නොබොන නිසා", "ජලය නොදිරවන නිසා", "වතුර හෝ වෙනත් දේ දීමෙන් පාචනය ඇතුළු බරපතළ විෂබීජ ආසාදන බිළිඳාට ඇතිවිය හැක."),
        q("කාන්තා ශ්‍රෝණි කුහරය තුළ ගර්භාෂය මුත්‍ර ආශයිකාවට සාපේක්ෂව පිහිටා ඇත්තේ කෙසේද?", "මුත්‍ර ආශයිකාවට පිටුපසින් සහ ගුද මාර්ගයට ඉදිරියෙන්", "මුත්‍ර ආශයිකාවට ඉදිරියෙන්", "වකුගඩු අසල", "පපුව ප්‍රදේශයේ", "ගර්භාෂය මුත්‍ර ආශයිකාව පිටුපසින් සහ ගුද මාර්ගයට ඉදිරියෙන් ශ්‍රෝණිය තුළ පිහිටා ඇත."),
        q("ශුක්‍රාණුවක හිසෙහි අඩංගු ඩිම්බයේ බිත්තිය විනිවිද යාමට උපකාරී වන එන්සයිම සහිත කොටස කුමක්ද?", "අග්‍රකාය හෙවත් ඇක්‍රොසෝමය (Acrosome)", "න්‍යෂ්ටිය", "මයිටොකොන්ඩ්‍රියාව", "කශිකාව", "ඇක්‍රොසෝමයේ ඇති එන්සයිම මගින් ඩිම්බයේ බාහිර පටලය දිය කර ශුක්‍රාණුව ඇතුළු වේ."),
        q("ශුක්‍රාණුවකට පිහිනා යාම සඳහා ශක්තිය ලබාදෙන මයිටොකොන්ඩ්‍රියා බහුලව පිහිටා ඇත්තේ ශුක්‍රාණුවේ කුමන කොටසෙහිද?", "මැද කොටසෙහි (Middle piece)", "හිසෙහි", "වලිගයේ අග", "පටලයේ", "මැද කොටසේ ඇති මයිටොකොන්ඩ්‍රියා මගින් ATP ශක්තිය සපයයි."),
        q("ශුක්‍රාණුවට ජලීය පරිසරයේ පිහිනා යාමට උපකාරී වන ව්‍යුහය කුමක්ද?", "කශිකාව හෙවත් වලිගය (Flagellum / Tail)", "අග්‍රකාය", "කේන්ද්‍රිකාව", "ප්ලාස්ම පටලය", "වලිගයේ කස පහර වැනි චලනය මගින් ශුක්‍රාණුව ඉදිරියට පිහිනා යයි."),
        q("වැඩිවියට පත් නිරෝගී පිරිමියෙකුගේ එක් ශුක්‍ර මෝචනයකදී සාමාන්‍යයෙන් පිටවන ශුක්‍රාණු සංඛ්‍යාව කොපමණද?", "මිලියන 100 සිට 300 දක්වා (මිලියන සිය ගණනක්)", "දහසක් පමණි", "එක් ශුක්‍රාණුවක් පමණි", "බිලියන දහයක්", "එක් වරකට මිලියන 100-300ත් අතර ශුක්‍රාණු සංඛ්‍යාවක් පිටවේ."),
        q("ලිංගිකව සම්ප්‍රේෂණය වන ආසාදන (STIs) මෙන්ම අනවශ්‍ය ගැබ් ගැනීම්ද එකවර වළක්වා ගත හැකි එකම උපත් පාලන ක්‍රමය කුමක්ද?", "කොන්ඩම් (Condoms) භාවිතය", "උපත් පාලන පෙති", "වාසෙක්ටමි", "ගර්භාෂ ලූපය", "කොන්ඩම් මගින් ශාරීරික තරල හුවමාරුව සම්පූර්ණයෙන් වළක්වන බැවින් ද්විත්ව ආරක්ෂාවක් ලැබේ."),
        q("ක්ලැමීඩියා (Chlamydia) ආසාදනය කාන්තාවන් තුළ හඳුනා නොගෙන ප්‍රතිකාර නොකළහොත් ඇතිවිය හැකි දිගුකාලීන සංකූලතාව කුමක්ද?", "ශ්‍රෝණි ප්‍රදාහ රෝගය (PID) සහ වඳභාවය (Infertility)", "දියවැඩියාව", "අධික තරබාරුව", "හෘදයාබාධ", "පැපොලෝපීය නාල අවහිර වී සදාකාලික වඳභාවයට පත්වීමට ක්ලැමීඩියා හේතු විය හැක."),
        q("සිෆිලිස් ආසාදිත මවකගෙන් කුස තුළ සිටින කලලයට රෝගය සම්ප්‍රේෂණය වීම හඳුන්වන්නේ කෙසේද?", "සහජ සිෆිලිස් (Congenital Syphilis)", "ප්‍රාථමික සිෆිලිස්", "ද්විතියික සිෆිලිස්", "අත්පත් කරගත් සිෆිලිස්", "වැදෑමහ හරහා කලලයට බැක්ටීරියාව ඇතුළු වී දරුවා විකෘතිතා සහිතව උපත ලැබීම Congenital Syphilis වේ."),
        q("කාන්තාවන්ගේ ඩිම්බ කෝෂවලින් හෝමෝන අසමතුලිතතාව නිසා කුඩා ගෙඩි හටගෙන ඔසප් අක්‍රමවත් වන රෝගී තත්ත්වය කුමක්ද?", "බහු-සිස්ටික් ඩිම්බ කෝෂ සින්ඩ්‍රෝමය (PCOS)", "ගැබ්ගෙල පිළිකාව", "ගොනෝරියාව", "ඒඩ්ස්", "PCOS තත්ත්වයේදී හෝමෝන අසමතුලිත වී බර වැඩිවීම, අනවශ්‍ය රෝම වර්ධනය හා ඔසප් අක්‍රමිකතා හටගනී."),
        q("නව යොවුන් වියේ ගැහැනු ළමුන්ට ආර්තව සමයේදී යකඩ ඌනතාව නිසා හටගත හැකි ප්‍රධාන පෝෂණ ගැටලුව කුමක්ද?", "රක්තහීනතාව (Iron Deficiency Anaemia)", "මන්දපෝෂණය", "රිකට්ස්", "ගලගණ්ඩය", "ආර්තවය මගින් රුධිරය පිටවීම නිසා යකඩ ඌනතා රක්තහීනතාව බහුලව ඇතිවිය හැක."),
        q("නව යොවුන් වියේ දරුවන්ගේ මුහුණේ කුරුලෑ (Acne) හටගැනීමට ප්‍රධාන හේතුව කුමක්ද?", "හෝමෝන වෙනස්කම් නිසා සමේ ස්නේහස්‍රාවී ග්‍රන්ථිවලින් (Sebaceous glands) තෙල් ස්‍රාවය වැඩිවීම හා විෂබීජ අවහිර වීම", "අධික ලෙස ජලය පානය කිරීම", "පොත් කියවීම", "ක්‍රීඩා කිරීම", "ඇන්ඩ්‍රොජන් හෝමෝන මගින් තෙල් ග්‍රන්ථි උත්තේජනය වී දූවිලි හා බැක්ටීරියා සිරවීමෙන් කුරුලෑ හටගනී."),
        q("කුරුලෑ පාලනය කිරීම සඳහා නව යොවුන් වියේදී අනුගමනය කළ යුතු සරලම පියවර කුමක්ද?", "දිනපතා මුහුණ මෘදු සබන් හා ජලයෙන් සේදීම සහ කුරුලෑ ඇඟිලිවලින් මිරිකීමෙන් වැළකීම", "කුරුලෑ තදින් නියපොතුවලින් කඩා දැමීම", "තෙල් සහිත ක්‍රීම් වර්ග ආලේප කිරීම", "මුහුණ නොසේද සිටීම", "කුරුලෑ කැඩීමෙන් විෂබීජ ගැඹුරට ගොස් මුහුණේ කැළැල් ස්ථිරව ඉතිරි වේ."),
        q("යොවුන් වියේ පසුවන දරුවන්ගේ චිත්තවේගීය වෙනස්කම් සහ ක්ෂණික කෝපය පාලනය කර ගැනීමට උපකාරී වන ක්‍රියාකාරකම කුමක්ද?", "ක්‍රීඩා, සෞන්දර්යාත්මක කටයුතු හෝ විනෝදාංශවල නිරත වීම", "කාමරයක තනිව සිරවීම", "මත්ද්‍රව්‍ය ගැනීම", "ආහාර නොගෙන සිටීම", "ක්‍රීඩාව හා විනෝදාංශ මගින් මානසික ආතතිය ඵලදායී ලෙස මුදාහැරීමට මග සැලසේ."),
        q("තමාගේ ශරීරයේ සිදුවන වෙනස්කම් ගැන ලැජ්ජාවට පත් නොවී ධනාත්මක ආකල්පයකින් යුතුව පිළිගැනීම හඳුන්වන්නේ කෙසේද?", "ධනාත්මක දේහ ප්‍රතිරූපය (Positive Body Image)", "ආත්මාර්ථකාමිත්වය", "සමාජ විරෝධී බව", "මානසික බිඳවැටීම", "තම ශරීරයේ ස්වභාවික වෙනස්කම් ගෞරවයෙන් හා ආත්ම විශ්වාසයෙන් යුතුව පිළිගැනීම වැදගත් වේ."),
        q("අනවශ්‍ය ගැබ් ගැනීමක් වැළැක්වීමට හදිසි අවස්ථාවකදී පැය 72ක් ඇතුළත භාවිත කරන ඖෂධය කුමක්ද?", "හදිසි උපත් පාලන පෙති (Emergency Contraceptive Pills — ECP)", "පැරසිටමෝල්", "පෙනිසිලින්", "ඇස්ප්‍රින්", "අනාරක්ෂිත ලිංගික එක්වීමකින් පසු පැය 72ක් ඇතුළත ගන්නා ECP මගින් ඩිම්බ මෝචනය හෝ රෝපණය වළක්වයි."),
        q("හදිසි උපත් පාලන පෙති (ECP) සාමාන්‍ය උපත් පාලන ක්‍රමයක් ලෙස නිතර භාවිත නොකළ යුත්තේ මන්ද?", "අධික හෝමෝන සාන්ද්‍රණය නිසා ආර්තව චක්‍රය දැඩි ලෙස අවුල් වන බැවින්", "එයින් උස අඩු වන නිසා", "එය කිසිසේත් ක්‍රියා නොකරන නිසා", "කිසිදු හානියක් නැති නිසා", "නිතර ECP භාවිතයෙන් ඔසප් චක්‍රය සහ හෝමෝන සමතුලිතතාවය බරපතළ ලෙස බිඳ වැටේ."),
        q("පිරිමින්ගේ ශුක්‍ර ප්‍රණාලය ශල්‍යකර්මයකින් කපා ගැටගැසීම මගින් සිදුකරන ස්ථිර උපත් පාලන ක්‍රමය කුමක්ද?", "වාසෙක්ටමි (Vasectomy)", "ටියුබෙක්ටමි", "ලූපය දැමීම", "හෝමෝන එන්නත", "ශුක්‍ර ප්‍රණාලය කැපීමෙන් ශුක්‍රාණු ශුක්‍ර තරලයට එක්වීම ස්ථිරවම වළකී."),
        q("කාන්තාවන්ගේ පැපොලෝපීය නාල කපා ගැටගැසීම මගින් සිදුකරන ස්ථිර උපත් පාලන ක්‍රමය කුමක්ද?", "එල්.ආර්.ටී. හෙවත් ටියුබෙක්ටමි (LRT — Ligation and Resection of Tubes)", "වාසෙක්ටමි", "කොන්ඩම්", "ගර්භාෂ ඉවත් කිරීම", "පැපොලෝපීය නාල වැසීමෙන් ඩිම්බය ශුක්‍රාණු සමග හමුවීම ස්ථිරවම නතර වේ."),
        q("ගර්භණී සමයේදී කලලයට අහිතකර ලෙස බලපාන බැවින් ගර්භණී මව සම්පූර්ණයෙන්ම වැළකී සිටිය යුතු ද්‍රව්‍ය මොනවාද?", "දුම්පානය, මත්පැන් සහ වෛද්‍ය උපදෙස් නොමැති ඖෂධ ගැනීම", "පලතුරු ආහාරයට ගැනීම", "ජලය පානය කිරීම", "සැහැල්ලු ව්‍යායාම", "මත්පැන් හා දුම්කොළ මගින් කලලයට ඔක්සිජන් අඩුවී බරපතළ විකෘතිතා (Fetal Alcohol Syndrome) හටගනී."),
        q("ලිංගික සම්ප්‍රේෂණ ආසාදනයක් ඇතැයි සැක කළ වහාම පුද්ගලයෙකු කළ යුතු වඩාත් සුදුසු පියවර කුමක්ද?", "ලැජ්ජාවෙන් තොරව කඩිනමින් රජයේ ලිංගාශ්‍රිත රෝග සායනයකට (STD Clinic) ගොස් පරීක්ෂා කර ගැනීම", "ඖෂධහලකින් හිතුමතේ පෙති බීම", "කිසිවෙකුට නොකියා සැඟවීම", "පාරම්පරික තෙල් ආලේප කිරීම", "රහස්‍යභාවය සුරකිමින් නිවැරදි වෛද්‍ය පරීක්ෂාවකට යොමු වීමෙන් රෝගය සුව කරගත හැක."),
        q("ලිංගික රෝගයකට ප්‍රතිකාර ලබාගැනීමේදී අනුගමනය කළ යුතු අත්‍යවශ්‍ය මූලධර්මයක් වන්නේ කුමක්ද?", "තමා මෙන්ම තම ලිංගික සහකරු හෝ සහකාරියද එකවර පරීක්ෂාවට හා ප්‍රතිකාරවලට ලක් කිරීම", "තමා පමණක් බෙහෙත් බීම", "සහකරුට නොදැන්වීම", "අඩක් බී බෙහෙත් නැවැත්වීම", "සහකරුට ප්‍රතිකාර නොකළහොත් නැවත නැවතත් රෝගය බෝවීම (Ping-pong infection) සිදුවේ."),
        q("නව යොවුන් වියේදී ප්‍රජනක සෞඛ්‍යය පිළිබඳ නිවැරදි විද්‍යාත්මක දැනුම ලබාගැනීමේ වැදගත්කම කුමක්ද?", "නොමඟ යාම්, මිථ්‍යා මත සහ අනවශ්‍ය බිය දුරු කරගෙන සෞඛ්‍ය සම්පන්න වගකීම් සහගත වැඩිහිටියෙකු ලෙස ගොඩනැගීමට", "විභාග සමත් වීමට පමණක්", "ශාරීරිකව දුර්වල වීමට", "සමාජයෙන් ඈත් වීමට", "නිවැරදි දැනුම මගින් වගකීම් සහගත තීරණ ගැනීමට සහ ලිංගික රෝගවලින් ආරක්ෂා වීමට හැකිවේ."),
        q("මිතුරන්ගේ හෝ අන්තර්ජාලයේ ඇති වැරදි තොරතුරු වෙනුවට ප්‍රජනක සෞඛ්‍ය ගැටලුවකදී උපදෙස් පැතිය යුත්තේ කාගෙන්ද?", "වෛද්‍යවරුන්, පාසල් සෞඛ්‍ය වෛද්‍ය නිලධාරීන් හෝ සුදුසුකම් ලත් උපදේශකයන්ගෙන්", "නොදන්නා මිතුරන්ගෙන්", "සමාජ මාධ්‍ය වීඩියෝවලින් පමණක්", "ඕපාදූපවලින්", "වෛද්‍ය නිලධාරීන්ගෙන් සහ ගුරුවරුන්ගෙන් විද්‍යාත්මකව නිවැරදි මාර්ගෝපදේශ ලබාගත හැක.")
    )
}
